"""Small provider-free guards; semantic judgments are never generated by tests."""
from copy import deepcopy
from hashlib import sha256
from pathlib import Path
from tempfile import TemporaryDirectory
import ast
import unittest

from genshin_corpus.retrieval import navi_g1_s1_audit as audit


def fixture():
    packets={'cases':[], 'supplementary_cases':[]}
    reviews={'cases':[], 'supplementary_cases':[]}
    evidence={'a':{'source':'1'}, 'b':{'source':'2'}}
    for n in range(50):
        key='cases' if n<48 else 'supplementary_cases'
        case_id=f'S{n+1:02d}' if n<48 else f'X{n-47:02d}'
        pair_id=str(n)
        packets[key].append({'case_id':case_id,'pair_id':pair_id,'sides':{
            'A':{'source_id':'1','title':'甲','delivered_ids':['a']},
            'B':{'source_id':'2','title':'乙','delivered_ids':['b']}}})
        reviews[key].append({'case_id':case_id,'pair_id':pair_id,'sources':['甲','乙'],
            'review_authority':audit.AUTHORITY,'human_acceptance':'NOT_REVIEWED','navigation_status':'INACTIVE',
            'grade_v02':'C','release_recommendation':'CATALOG_ONLY','reason_codes':['INCREMENT_INSUFFICIENT'],
            'proposition_decision':'仅目录','increment':'无剧情增量','source_limitations':'目录', 'reading_scope':'所给片段',
            'subpropositions':[{'role':'ORIGINAL_CORE','text':'同一商品','support':'EXPLICIT','grade':'C',
                'release':'CATALOG_ONLY','reason':'对应明确但无剧情增量','evidence_ids':{'A':['a'],'B':['b']}}]})
    return packets,reviews,evidence


class S1AuditGuards(unittest.TestCase):
    def test_full_denominator_and_explicit_catalog_are_valid(self):
        self.assertEqual(audit.validate_reviews(*fixture())['primary_count'],48)

    def test_failures_cannot_disappear_or_duplicate(self):
        for mode in ['missing','duplicate']:
            p,r,e=fixture()
            if mode=='missing':r['cases'].pop()
            else:r['cases'][-1]=deepcopy(r['cases'][0])
            with self.assertRaises(ValueError):audit.validate_reviews(p,r,e)

    def test_supplements_are_a_separate_complete_denominator(self):
        for mode in ['missing','duplicate','primary']:
            p,r,e=fixture()
            if mode=='missing':r['supplementary_cases'].pop()
            elif mode=='duplicate':r['supplementary_cases'][1]=deepcopy(r['supplementary_cases'][0])
            else:r['supplementary_cases'].append(deepcopy(r['cases'][0]))
            with self.assertRaisesRegex(ValueError,'Supplementary'):audit.validate_reviews(p,r,e)

    def test_cross_endpoint_or_undelivered_ids_fail(self):
        for ids in [['b'],['invented']]:
            p,r,e=fixture();r['cases'][0]['subpropositions'][0]['evidence_ids']['A']=ids
            with self.assertRaises(ValueError):audit.validate_reviews(p,r,e)

    def test_human_or_active_status_cannot_be_promoted(self):
        for k,v in [('human_acceptance','ACCEPTED'),('navigation_status','ACTIVE'),('review_authority','HUMAN')]:
            p,r,e=fixture();r['cases'][0][k]=v
            with self.assertRaisesRegex(ValueError,'authority'):audit.validate_reviews(p,r,e)

    def test_D_requires_error_and_cannot_derive_only_from_guard(self):
        p,r,e=fixture();row=r['cases'][0];sp=row['subpropositions'][0]
        row['grade_v02']='D';row['release_recommendation']='EXCLUDED';sp.update(grade='D',release='EXCLUDED')
        with self.assertRaisesRegex(ValueError,'D requires'):audit.validate_reviews(p,r,e)
        sp['critical_error']='关键对象错误';audit.validate_reviews(p,r,e)
        sp['role']='COUNTERFACTUAL_GUARD'
        with self.assertRaisesRegex(ValueError,'added guard'):audit.validate_reviews(p,r,e)

    def test_B_label_and_release_are_independent(self):
        p,r,e=fixture();row=r['cases'][0];sp=row['subpropositions'][0]
        row.update(grade_v02='B',release_recommendation='REVIEW_REQUIRED')
        sp.update(grade='B',release='REVIEW_REQUIRED',support='GROUNDED_INTERPRETATION')
        with self.assertRaisesRegex(ValueError,'label'):audit.validate_reviews(p,r,e)
        sp['navigation_label']='解释性联读 / 非确定史实';audit.validate_reviews(p,r,e)
        row.update(grade_v02='C',release_recommendation='ELIGIBLE_PENDING_RELEASE')
        with self.assertRaisesRegex(ValueError,'requires A/B'):audit.validate_reviews(p,r,e)

    def test_orientation_cannot_be_silently_reversed(self):
        p,r,e=fixture();r['cases'][0]['sources'].reverse()
        with self.assertRaisesRegex(ValueError,'orientation'):audit.validate_reviews(p,r,e)

    def test_unicode_range_and_hash_are_exact(self):
        text='月亮。\n传说未证实。'
        record={'record_id':'record','sections':[{'ordinal':1,'units':[{'ordinal':2,'value':{'normalized_text':text}}]}]}
        s={'record_id':'record','section':1,'unit':2,'start':4,'end':len(text),'text':text[4:]}
        s['text_sha256']=sha256(s['text'].encode()).hexdigest();audit.verify_span(s,record)
        s['text']=s['text'].replace('未证实','已证实');s['text_sha256']=sha256(s['text'].encode()).hexdigest()
        with self.assertRaisesRegex(ValueError,'range'):audit.verify_span(s,record)

    def test_freeze_hash_precedes_unmask_and_artifacts_are_create_only(self):
        p,r,e=fixture()
        with TemporaryDirectory() as tmp:
            root=Path(tmp)
            for name,value in [('pass1-packets.json',p),('evidence.json',e),('draft.json',r)]:audit.put(root/name,value)
            audit.freeze(root,root/'draft.json')
            (root/'pass1-reviews-frozen.json').write_text('{}',encoding='utf-8')
            with self.assertRaisesRegex(ValueError,'Frozen'):audit.compare(root)
            with self.assertRaises(FileExistsError):audit.put(root/'draft.json',r)

    def test_audit_module_imports_only_standard_library(self):
        tree=ast.parse(Path(audit.__file__).read_text(encoding='utf-8'))
        allowed={'__future__','argparse','collections','csv','gzip','hashlib','json','pathlib','re'}
        for node in ast.walk(tree):
            if isinstance(node,ast.Import):self.assertTrue({x.name for x in node.names}<=allowed)
            elif isinstance(node,ast.ImportFrom):self.assertIn(node.module,allowed)


if __name__=='__main__':
    unittest.main()
